const $=s=>document.querySelector(s);
const esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const views=[['overview','◫','Overview'],['roadmap','⌁','Roadmap'],['tickets','▤','Tickets'],['agents','⬡','Agent roles'],['changes','↗','Changes'],['merges','⑂','Merge workbench'],['history','◷','Decision history'],['decisions','⚖','Own decisions'],['evaluations','✓','Evaluations'],['signals','≋','Signals'],['runtime','↻','Target run']];
let snapshot={},updated=null,busy=false,ticketSearch='',ticketStatus='Live work',ticketTier='All tiers',ticketDetail=null,documentDetail=null,walkAt=0,walkNote='';
const data=k=>snapshot[k]?.ok?snapshot[k].data:null;
const panel=(title,body)=>`<section class="panel"><div class="panel-head"><h2>${esc(title)}</h2></div><div class="pad">${body}</div></section>`;
const empty=t=>`<p>${esc(t)}</p>`;
const details=x=>`<details><summary>Inspect evidence</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(JSON.stringify(x,null,2))}</pre></details>`;
const runText=r=>!r||typeof r!=='object'?r:(r.label||`${r.project} started ${r.started}${r.archive?` (archive ${r.archive})`:''}`);
const badge=t=>`<span class="badge">${esc(t)}</span>`;
function flatten(node){return node?[node,...(node.subGoals||[]).flatMap(flatten)]:[]}
function events(){return Array.isArray(data('live')?.recent)?data('live').recent:[]}
function evidence(rows,message){return rows.length?`<div class="timeline">${rows.map(e=>`<div class="event"><small>${esc(e.timestamp||e.at||'')} · ${esc(e.cycleId||'')}</small><h3>${esc(e.event||e.kind||e.subject||'Record')}</h3>${details(e)}</div>`).join('')}</div>`:empty(message)}
// M-H: what a review makes Autobuilder do, by the kind of entry and where it is recorded (TicketActions).
const effectOf=(d,a)=>{const e=d.entry,c=e.checker||{},kept=/KEEP|CORRECT/.test(c.outcome||''),own=d.project==='autobuilder-roadmap';
 if(d.project.includes('(archive '))return 'recorded only; Autobuilder does not act on it (the project\'s state is gone)';
 if(a==='DISAGREE')return own?(e.kind==='TICKET_CREATED'?'Autobuilder retracts the ticket it created':e.kind==='TICKET_CHANGED'?'Autobuilder withdraws the note it appended':'recorded; a session acts on it (M-H)'):e.kind==='DRAFT_INVESTIGATED'?'Autobuilder investigates the draft once more, with your reason':kept?'Autobuilder retracts what was made of the draft':'Autobuilder acts on the draft after all';
 return own&&(e.kind||'').startsWith('TICKET_')?'Autobuilder appends it to the ticket':'nothing happens (agreeing or asking needs no action from Autobuilder)'};
// A correction is a new review naming the one it revises; the earlier one stays, the newer one counts.
const reviseForm=d=>{const last=d.reviews[d.reviews.length-1];if(!last)return '';const was=last.assessment||last['v'+'erdict'];const disagreedBefore=d.reviews.some(r=>(r.assessment||r['v'+'erdict'])==='DISAGREE');
 return `<details><summary>Revise this review</summary><form data-revise="${esc(d.entry.id)}" data-project="${esc(d.project)}" data-revises="${esc(last.at)}" style="margin-top:8px"><p>Revises the review of ${esc((last.at||'').slice(0,19))} (${esc(was)} · ${esc(last.reviewer)}). The earlier review stays in the record; yours is appended after it and is the one that counts.</p><select name="assessment" aria-label="assessment">${['AGREE','DISAGREE','QUESTION'].map(a=>`<option${a!==was&&a==='DISAGREE'?' selected':''}>${a}</option>`).join('')}</select> <input name="reason" aria-label="reason" required placeholder="why you revise it (required)" style="width:55%"> <button>Append the revision</button><br><small>DISAGREE: ${esc(effectOf(d,'DISAGREE'))}. AGREE or QUESTION: ${esc(effectOf(d,'AGREE'))}.${disagreedBefore?' An earlier DISAGREE may already have made Autobuilder act; a revision does not undo that -- a session restores it by appending to the ticket.':''}</small> <small class="revise-result"></small></form></details>`};
function render(){
 let view=location.hash.slice(1)||'overview';if(!views.some(v=>v[0]===view))view='overview';
 const status=data('status'),live=data('live'),home=data('home'),start=data('start');
 const connected=!!snapshot.status?.ok,goals=flatten(data('goals')),conflicts=data('conflicts');
 $('#nav').innerHTML=views.map(([id,icon,title])=>`<a href="#${id}" class="${id===view?'active':''}"><span>${icon}</span>${title}</a>`).join('');
 $('#crumb').textContent=$('#heading').textContent=views.find(v=>v[0]===view)[2];
 $('#subtitle').textContent=connected?'Autobuilder development evidence · refreshes every 5 seconds':'Run backend unavailable · reconnecting every 5 seconds';
 $('#connection').textContent=data('meta')?'Autobuilder development sources':'Development sources unavailable';
 $('#updated').textContent=updated?`Last checked ${updated.toLocaleTimeString()}`:'Connecting…';
 $('#workspace-name').textContent='Autobuilder development';
 $('#mode').textContent=connected?'LIVE WORKSPACE':'DISCONNECTED';
 const unavailable=k=>snapshot[k]&&!snapshot[k].ok?panel('Source unavailable',empty(snapshot[k].error)):'';
 let html='';
 if(view==='runtime'){
  const metrics=[['Cycle',status?.cycleName??'No cycle'],['Score',status?.score!=null?status.score.toFixed(3):'—'],['Merged',live?.merged??'—'],['Open conflicts',Array.isArray(conflicts)?conflicts.length:'—']];
  html=`<div class="stats">${metrics.map(([t,n])=>`<div class="stat"><div class="label">${esc(t)}</div><strong style="font-size:22px;overflow-wrap:anywhere">${esc(n)}</strong></div>`).join('')}</div>`;
  html+=panel('Current work',`<h3>${esc(status?.currentSubGoalDescription||live?.workingOn||'No current subgoal reported')}</h3><p>${esc(status?.goalProgress)} · ${esc(status?.mutationState)}</p>`);
  html+=panel('Current goal',`<p style="white-space:pre-wrap">${esc(status?.currentGoalDescription||'No goal reported')}</p>`);
  html+=panel('Recent activity',evidence(events().slice(0,12),'No recent events reported.'))+unavailable('status');
 }
 if(view==='roadmap'){
  const dev=data('development');
  html=panel('Autobuilder development roadmap',empty('Source: .claude-memory/roadmap.md · authoritative ticket markers. Built, declined, obsoleted, subsumed, and retracted remain distinct outcomes.'));
  if(dev){
   html+=panel('Queue census',Object.entries(dev.counts).map(([status,count])=>`<div class="row"><h3>${esc(status)}</h3>${badge(count)}</div>`).join(''));
   const tiers=[...new Set(dev.tickets.map(t=>t.tier))];
   html+=panel('Work by tier',tiers.map(tier=>{const rows=dev.tickets.filter(t=>t.tier===tier);const counts={};rows.forEach(t=>counts[t.status]=(counts[t.status]||0)+1);return `<div class="row"><div><h3>${tier==='M'?'Maintenance':`Tier ${esc(tier)}`}</h3><p>${Object.entries(counts).map(([k,v])=>`${v} ${esc(k)}`).join(' · ')}</p></div><a class="link" href="#tickets" data-tier="${esc(tier)}">Inspect tickets ↗</a></div>`}).join(''));
  }
 }
 if(view==='tickets'){
  const dev=data('development'),statuses=['Live work','All statuses',...Object.keys(dev?.counts||{})];
  const select=(id,values,value)=>`<select id="${id}" aria-label="${id}">${values.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select>`;
  html=`<div class="toolbar"><input id="ticket-search" aria-label="Search development tickets" placeholder="Search ID or title…" value="${esc(ticketSearch)}">${select('ticket-status',statuses,ticketStatus)}${select('ticket-tier',['All tiers',...[...new Set((dev?.tickets||[]).map(t=>t.tier))]],ticketTier)}</div>`;
  const rows=(dev?.tickets||[]).filter(t=>(ticketStatus==='All statuses'||(ticketStatus==='Live work'?['open','in progress'].includes(t.status):t.status===ticketStatus))&&(ticketTier==='All tiers'||t.tier===ticketTier)&&`${t.id} ${t.title}`.toLowerCase().includes(ticketSearch.toLowerCase()));
  html+=panel(`${rows.length} matching development tickets`,rows.length?`<table><thead><tr><th>TICKET</th><th>STATUS</th><th>SOURCE</th></tr></thead><tbody>${rows.map(t=>`<tr><td><button data-ticket="${esc(t.id)}">${esc(t.id)}</button><p>${esc(t.title)}</p></td><td>${badge(t.status)}</td><td>roadmap.md:${t.line}</td></tr>`).join('')}</tbody></table>`:empty('No tickets match these filters.'));
  if(ticketDetail)html+=panel(ticketDetail.id,`<p>${esc(ticketDetail.status)} · ${esc(ticketDetail.source)}:${ticketDetail.line}</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere;max-height:65vh;overflow:auto">${esc(ticketDetail.text||ticketDetail.error)}</pre>`);
  // T4-FG rule 7: the path of a carry-through for this ticket -- why it was selected, which run, the evidence on that
  // run's final tree, the outcome -- and every decision recorded against the ticket, with its reviews. Shown as written.
  if(ticketDetail&&(ticketDetail.carry||[]).length)html+=panel(ticketDetail.id+' — carry-through',ticketDetail.carry.map(a=>{const s=a.selection||{},e=a.evidence||{},p=e.patch||{},c=e.check||{},su=x=>x?`${x.cases} cases, ${x.fail} failing, ${x.skipped} skipped (exit ${x.exit})`:'not run';return `<h3>Attempt ${esc(a.attempt)}</h3>
<p><b>Selected</b> by decision ${esc(s.decision)} at commit <code>${esc((s.pinned||'').slice(0,8))}</code>: ${esc(s.reason)}</p>
<p><b>Passed over:</b> ${(s.passed_over||[]).map(x=>`${esc(x.ticket)} — ${esc(x.reason)}`).join('; ')||'—'}</p>
<p><b>Stated check</b> (${esc((s.acceptance_check||{}).instrument)}): ${esc((s.acceptance_check||{}).what)} — on ${esc((s.acceptance_check||{}).tree)}</p>
<p><b>Files named:</b> ${(s.files||[]).map(f=>`<code>${esc(f)}</code>`).join(', ')||'—'}</p>
<p><b>Run:</b> ${esc(a.run)} (case ${esc(a.case)}) — terminal ${esc(e.run_terminal)}, its yardstick on the final tree ${esc(e.run_yardstick_final_tree)}</p>
<p><b>Graded:</b> ${esc(e.graded_tree)}</p>
<p><b>Patch:</b> ${(p.modified||[]).length} modified, ${(p.added||[]).length} added, ${(p.removed||[]).length} removed — applies to the pinned commit: ${esc(p.applies_to_pinned)} — <code>${esc(p.path)}</code></p>
<p><b>Full suite</b> at the pinned commit: ${su(e.suite_pinned)}; with the patch: ${su(e.suite_patched)}; regressions: ${(e.regressions||[]).length}</p>
<p><b>Check:</b> ${esc(c.passed)} of ${esc(c.cases)} added case(s) pass ${(c.test_classes_added||[]).length?'('+c.test_classes_added.map(esc).join(', ')+')':''}</p>
${e.error?`<p><b>Not evidence:</b> ${esc(e.error)}</p>`:''}<p><b>Outcome:</b> ${esc(a.outcome)}</p>`}).join('<hr>'));
  if(ticketDetail&&(ticketDetail.decisions||[]).length)html+=panel(ticketDetail.id+' — decisions recorded against it',ticketDetail.decisions.map(d=>{const x=d.entry||{};return `<p><b>${esc(x.id)}</b> ${esc(x.kind)} · ${esc((x.at||'').slice(0,19))} · ${esc(x.decision)}${x.follows?` · follows ${esc(x.follows)}`:''}</p><p>${esc(x.why)}</p>${(d.reviews||[]).map(r=>`<p>↳ review: ${esc(r.assessment)} by ${esc(r.reviewer)} — ${esc(r.reason)}</p>`).join('')}`}).join('<hr>'));
 }
 const meta=data('meta'),repo=meta?.git?.data,dev=data('development');
 const docs=meta?.documents||[];
 const docList=rows=>rows.map(d=>`<div class="row"><div><h3>${esc(d.title)}</h3><small>${esc(d.path)}</small></div><button data-document="${esc(d.path)}">Read record</button></div>`).join('')||empty('No matching development records.');
 const ticketLinks=ids=>ids.map(id=>`<a href="#tickets" data-ticket-link="${esc(id)}">${esc(id)}</a>`).join(' · ');
 const commits=()=>repo?repo.commits.map(c=>`<div class="event"><small>${esc(c.at)} · ${esc(c.sha.slice(0,10))}</small><h3>${esc(c.title)}</h3><p>${ticketLinks(c.tickets)}</p></div>`).join(''):empty(meta?.git?.error||'Git data unavailable.');
 if(view==='overview'){
  const counts=dev?.counts||{};
  html=panel('Autobuilder development',`<p>Architecture, decisions, implementation and evidence for Autobuilder itself.</p><p>Branch: ${esc(repo?.branch)} · HEAD: ${esc(repo?.head?.slice(0,10))}</p>`);
  html+=`<div class="stats">${[['Open tickets',counts.open??'—'],['In progress',counts['in progress']??0],['Deferred',counts.deferred??'—'],['Changed tracked files',repo?.changed.length??'—']].map(([t,n])=>`<div class="stat"><div class="label">${esc(t)}</div><strong>${esc(n)}</strong></div>`).join('')}</div>`;
  html+=panel('Recent development',commits())+panel('Working principles and design',docList(docs.filter(d=>/meta_process|three_disciplines|meta_layer/.test(d.path))));
 }
 if(view==='agents'){
  const responsibilities={planner:'Plans subgoals and their acceptance criteria.',evolution:'Produces candidate code changes.',evaluation:'Judges candidate mutations with model and heuristic evidence.',merge:'Applies accepted mutations and records their provenance.',analysis:'Finds structural issues and proposes work.'};
  html=panel('Roles inside Autobuilder',empty('These are the execution roles implemented by Autobuilder. Development ownership is not inferred from these roles.'));
  html+=panel('Implementation and protocol contracts',(meta?.roles||[]).map(r=>`<div class="row"><div><h3>${esc(r.role)}</h3><p>${esc(responsibilities[r.role])}</p>${[...r.sources,...r.contracts].map(path=>`<small style="display:block">${esc(path)}</small>`).join('')}<p>Related development tickets: ${ticketLinks((dev?.tickets||[]).filter(t=>t.title.toLowerCase().includes(r.role)).slice(0,8).map(t=>t.id))}</p></div></div>`).join(''));
 }
 if(view==='changes')html=panel('Uncommitted Autobuilder changes',repo?`<p>Tracked changes: ${repo.changed.length}. Untracked paths: ${repo.untracked.length}. Includes work by other sessions.</p><pre style="white-space:pre-wrap">${esc(repo.changed.join('\n')||'No tracked changes.')}</pre><details><summary>Untracked paths</summary><pre style="white-space:pre-wrap">${esc(repo.untracked.join('\n'))}</pre></details>`:empty(meta?.git?.error||'Git unavailable.'))+panel('Recent commits · ticket references from commit titles',commits());
 if(view==='merges')html=panel('Autobuilder Git conflicts',repo?repo.conflicts.length?`<pre>${esc(repo.conflicts.join('\n'))}</pre>`:empty('No unresolved Git index conflicts in the Autobuilder checkout.'):empty('Git conflict status unavailable.'))+panel('Port and integration reviews',docList(docs.filter(d=>d.path.startsWith('process/'))))+panel('Review boundary',empty('These records concern changes entering Autobuilder itself. Review packets preserve proposed, loop-built and reference alternatives. This view does not apply merges or invent LLM options.'));
 if(view==='history')html=panel('Recorded development decisions',docList(docs.filter(d=>d.path.startsWith('.claude-memory/'))))+panel('Resulting development history',commits());
 if(view==='decisions'){
  const rec=data('decisions'),rows=rec?.decisions||[];
  html=panel('Decisions Autobuilder took on its own',empty(`Source: ${rec?.source||'data/*/meta/decisions.ndjson'} · append-only. Reviews are appended beside each entry -- here, or by a Claude session (scripts/review_decisions.py); Autobuilder follows them at its next proposal (DISAGREE on a ticket it created retracts it). Nothing waits for them. Unreviewed: ${rec?.unreviewed??'—'} of ${rows.length}.`));
  // M-H, the operator's walk through the open topics: one at a time, the entry, what it rests on, and the session's
  // recommendation; confirm it, correct it, disagree, or skip. Every action is one appended review; nothing is erased.
  // oldest first, as scripts/review_decisions.py numbers them, so '#3' means the same topic in a session and here
  const open=rows.filter(d=>!d.reviews.length&&d.needs_review!==false).sort((a,b)=>(a.entry.at||'').localeCompare(b.entry.at||''));
  if(!open.length&&rows.length)html+=panel('No open topics',`<p>Every decision has been reviewed. The list below is the history: each entry with the review appended beside it. Nothing there is waiting for you.</p>`);
  if(open.length){const i=Math.min(walkAt,open.length-1),d=open[i],e=d.entry,c=e.checker||{},r=d.recommendation,kept=/KEEP|CORRECT/.test(c.outcome||'');
   const undo=d.project.includes('(archive ')?'recorded beside the archived copy only; Autobuilder does not act on it (the project\'s state is gone)':e.kind==='TICKET_CREATED'?'Autobuilder retracts the ticket it created':e.kind==='TICKET_CHANGED'?'Autobuilder withdraws the note it appended':e.kind==='DRAFT_INVESTIGATED'?'Autobuilder investigates the draft once more, with your reason':e.kind==='DRAFT_CHECKED'?(kept?'Autobuilder retracts what was made of the draft':'Autobuilder acts on the draft after all'):'recorded; a session acts on it (M-H)';
   const withRec=open.filter(x=>x.recommendation).length;
   html+=panel(`Walk through the open topics — ${i+1} of ${open.length}`,`<p>All open topics with the session's recommendation; click a row to open it below. <b>Confirm all</b> appends exactly the recommendations in this table, each recorded as accepted from the session.</p><table style="width:100%;border-collapse:collapse;font-size:13px"><tr style="text-align:left"><th>#</th><th>About</th><th>Kind</th><th>Recommendation</th><th>Why, in short</th></tr>${open.map((x,k)=>{const rr=x.recommendation,why=rr?String(rr.reason||''):'';return `<tr data-walk-go="${k}" style="cursor:pointer;border-top:1px solid rgba(127,127,127,.25);${k===i?'outline:2px solid currentColor;':''}"><td style="padding:4px 6px">${k+1}</td><td style="padding:4px 6px">${esc((x.entry.on||'').slice(0,90))}</td><td style="padding:4px 6px">${esc(x.entry.kind)}</td><td style="padding:4px 6px"><b>${esc(rr?rr.assessment:'none yet')}</b></td><td style="padding:4px 6px">${esc(why.length>140?why.slice(0,140)+'…':why)}</td></tr>`}).join('')}</table><p style="margin-top:8px">${withRec?`<button data-walk-all>Confirm all ${withRec} recommendation(s) in this table</button>`:''} <small class="walk-result">${esc(walkNote)}</small></p><hr><h3>Topic ${i+1} of ${open.length}</h3><p>${esc(d.project)} · ${esc((e.at||'').slice(0,19))} · ${esc(e.id)} · ${esc(e.kind)}${(e.tickets||[]).length?' · tickets '+ticketLinks(e.tickets):''} · checker ${badge(c.outcome||'none')}</p><p><b>On:</b> ${esc(e.on)}</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere;max-height:30vh;overflow:auto">${esc(e.decision)}</pre><p><b>Why:</b> ${esc(e.why)}</p><details><summary>What it read (${(e.read||[]).length}) and the checker's objections (${(c.objections||[]).length})</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc((e.read||[]).map(x=>`${x.holds?'holds':'NOT FOUND'}  ${x.source}:${x.line}  ${x.text}`).join('\n'))}\n\n${esc((c.objections||[]).join('\n---\n'))}</pre></details>
${r?`<div class="row" style="border-left:3px solid currentColor;padding-left:8px"><div><h3>Recommendation: ${esc(r.assessment)} · by ${esc(r.by)}</h3><p>${esc(r.reason)}</p></div></div><p><button data-walk-confirm="${i}">Confirm the recommendation</button></p>`:'<p><i>No recommendation from a session yet -- decide it yourself below, or skip it.</i></p>'}
<form data-walk-correct="${i}"><b>Decide yourself:</b> <select name="assessment" aria-label="assessment">${['AGREE','DISAGREE','QUESTION'].map(a=>`<option${r&&r.assessment===a?' selected':''}>${a}</option>`).join('')}</select> <input name="reason" aria-label="reason" required placeholder="your reason (required)" value="${esc(r?r.reason:'').replace(/^—$/,'')}" style="width:50%"> <button>Append as yours</button><br><small>Left unchanged, it is recorded as accepting the recommendation; change the assessment or the reason to make it yours. DISAGREE here: ${esc(undo)}. Nothing is erased: the entry stays, your review is appended beside it.</small></form>
<p><button data-walk-prev ${i===0?'disabled':''}>Previous</button> <button data-walk-skip ${i>=open.length-1?'disabled':''}>Skip to the next</button></p>`);
  }
  // The open topics are handled in the walkthrough above; this list is the history of reviewed decisions only.
  const reviewed=rows.filter(d=>d.reviews.length||d.needs_review===false);
  if(reviewed.length)html+=panel(`History: ${reviewed.length} reviewed decision(s)`,`<p>Each with the review appended beside it. Nothing here is waiting for you; a review can still be revised inside its entry.</p>`);
  html+=reviewed.length?reviewed.map(d=>{const e=d.entry,c=e.checker||{},isOpen=!d.reviews.length&&d.needs_review!==false;const body=`<p>${esc(d.project)} · ${esc((e.at||'').slice(0,19))} · run ${esc(runText(e.run))} · ${esc(e.id)}${(e.tickets||[]).length?' · tickets '+ticketLinks(e.tickets):''}${e.revises?' · revises '+esc(e.revises):''}</p><p>Checker: ${badge(c.outcome||'none')}</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere;max-height:30vh;overflow:auto">${esc(e.decision)}</pre><p><b>Why:</b> ${esc(e.why)}</p><details><summary>What it read (${(e.read||[]).length}) and the checker's objections (${(c.objections||[]).length})</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc((e.read||[]).map(r=>`${r.holds?'holds':'NOT FOUND'}  ${r.source}:${r.line}  ${r.text}`).join('\n'))}\n\n${esc((c.objections||[]).join('\n---\n'))}</pre></details>`;return panel(`${d.reviews.length?'reviewed':d.needs_review===false?'carries out a review':'UNREVIEWED'} · ${e.kind} · ${e.on||''}`,isOpen?`${body}<form class="review" data-review="${esc(e.id)}" data-project="${esc(d.project)}" style="margin-top:8px"><select name="assessment" aria-label="assessment"><option>AGREE</option><option>DISAGREE</option><option>QUESTION</option></select> <input name="reviewer" aria-label="reviewer" value="operator" style="width:9em"> <input name="reason" aria-label="reason" required placeholder="why (required)" style="width:40%"> <button>Append review</button><small class="review-result"></small></form>`:`<p>${esc(d.project)} · ${esc(e.id)}</p>${d.reviews.map(r=>`<div class="row"><div><h3>${esc(r.assessment||r['v'+'erdict'])} · ${esc(r.reviewer)}${r.revises?' · revises the review of '+esc(String(r.revises).slice(0,19)):''}</h3><p>${esc(r.reason)}</p><small>${esc((r.at||'').slice(0,19))}</small></div></div>`).join('')}<details><summary>The decision in full</summary>${body}</details>${reviseForm(d)}`)}).join(''):empty('No decision recorded yet.');
 }
 if(view==='evaluations'){
  const tests=meta?.tests;
  html=panel('Saved Autobuilder test evidence',empty('Reports already on disk, from target/surefire-reports. They may come from different invocations and do not establish that the current HEAD or uncommitted work passes. No tests are started by this view.'));
  if(tests)html+=panel('Report totals',details(tests.totals))+panel('Test suites',tests.reports.length?tests.reports.map(r=>`<div class="row"><div><h3>${esc(r.name)}</h3><small>${esc(r.source)}</small><p>File modified: ${esc(r.modified)}</p></div>${badge(`${r.tests} tests · ${r.failures} failures · ${r.errors} errors · ${r.skipped} skipped`)}</div>`).join(''):empty('No saved Surefire reports found.'))+(tests.errors.length?panel('Unreadable reports',details(tests.errors)):'');
  html+=panel('Review evidence',docList(docs.filter(d=>/ASSESSMENT|REVIEW/.test(d.path))));
 }
 if(view==='signals'){
  html=panel('Development queue observations',`<p>Derived from authoritative ticket markers and the current Git checkout. These observations do not steer Autobuilder’s execution loop.</p><div class="row"><h3>Open work</h3>${badge(dev?.counts.open??'Unavailable')}</div><div class="row"><h3>Deferred work</h3>${badge(dev?.counts.deferred??'Unavailable')}</div><div class="row"><h3>Unresolved Git conflicts</h3>${badge(repo?.conflicts.length??'Unavailable')}</div><div class="row"><h3>Tracked files with uncommitted work</h3>${badge(repo?.changed.length??'Unavailable')}</div>`)+panel('Signal architecture and development principles',docList(docs.filter(d=>/signal_consumer|three_disciplines/.test(d.path))));
 }
 if(documentDetail&&['overview','history','merges','evaluations','signals'].includes(view))html+=panel(documentDetail.path,`<p>${esc(documentDetail.modified||'')}</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere;max-height:65vh;overflow:auto">${esc(documentDetail.text||documentDetail.error)}</pre>`);
 const sourcesByView={overview:['development','meta'],roadmap:['development'],tickets:['development'],agents:['meta','development'],changes:['meta'],merges:['meta'],history:['meta'],evaluations:['meta'],signals:['meta','development'],decisions:['decisions'],runtime:['status','live','conflicts']};
 const sourcePaths={decisions:'Each project: data/*/meta/decisions.ndjson and decision-reviews.ndjson',meta:'Autobuilder repository · Git, source files, decision records and saved test reports',development:'Local repository: .claude-memory/roadmap.md',status:'/autobuilder/status',live:'/autobuilder/live',goals:'/autobuilder/goals/tree',imports:'/autobuilder/inputs/imports',conflicts:'/autobuilder/inputs/conflicts',start:'/autobuilder/start-state'};
 const sources=sourcesByView[view];
 const available=sources.filter(k=>snapshot[k]?.ok).length;
 $('#mode').textContent=available===sources.length?'LIVE VIEW':available?'PARTIAL DATA':'DATA UNAVAILABLE';
 $('#subtitle').textContent=available===sources.length?'Autobuilder development evidence · refreshes every 5 seconds':available?'Some API sources are unavailable · retrying every 5 seconds':'This view cannot load its API sources · retrying every 5 seconds';
 const provenance=panel('Sources for this view',sources.map(k=>`<div class="row"><div><small>${esc(sourcePaths[k])}</small><p>${snapshot[k]?.ok?'Connected':esc(snapshot[k]?.error||'Waiting for first response')}</p></div>${badge(snapshot[k]?.ok?'Available':'Unavailable')}</div>`).join(''));
 if(!available)html=empty('Data is unavailable. This does not mean that the project has no records.');
 $('#app').innerHTML=provenance+html;
 document.querySelectorAll('[data-document]').forEach(b=>b.onclick=async()=>{const path=b.dataset.document;documentDetail={path,text:'Loading…'};render();try{const r=await fetch('/api/documents/'+encodeURIComponent(path),{cache:'no-store'}),v=await r.json();documentDetail=v.ok?v.data:{path,error:v.error}}catch(e){documentDetail={path,error:e.message}}render()});
 const walkOpen=()=>(data('decisions')?.decisions||[]).filter(d=>!d.reviews.length&&d.needs_review!==false).sort((a,b)=>(a.entry.at||'').localeCompare(b.entry.at||''));
 const postReview=async body=>{const r=await fetch('/api/reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return r.json()};
 const accepted=d=>({decision:d.entry.id,project:d.project,assessment:d.recommendation.assessment,reason:d.recommendation.reason,reviewer:`operator, accepting ${d.recommendation.by}'s recommendation`});
 document.querySelectorAll('[data-walk-confirm]').forEach(b=>b.onclick=async()=>{const d=walkOpen()[+b.dataset.walkConfirm];if(!d)return;b.disabled=true;try{const v=await postReview(accepted(d));walkNote=v.ok?`${d.entry.id}: confirmed`:`${d.entry.id}: refused -- ${v.error}`}catch(e){walkNote='failed: '+e.message}refresh()});
 document.querySelectorAll('form[data-walk-correct]').forEach(f=>f.onsubmit=async ev=>{ev.preventDefault();const d=walkOpen()[+f.dataset.walkCorrect];if(!d)return;const r=d.recommendation,same=!!r&&f.assessment.value===r.assessment&&f.reason.value.trim()===String(r.reason||'').trim();try{const v=await postReview(same?accepted(d):{decision:d.entry.id,project:d.project,assessment:f.assessment.value,reason:f.reason.value,reviewer:'operator'});walkNote=v.ok?`${d.entry.id}: ${f.assessment.value} appended ${same?'(unchanged: recorded as accepting the recommendation)':'as yours'}`:`${d.entry.id}: refused -- ${v.error}`}catch(e){walkNote='failed: '+e.message}f.reason.blur();refresh()});
 document.querySelectorAll('[data-walk-skip]').forEach(b=>b.onclick=()=>{walkAt++;walkNote='';render()});
 document.querySelectorAll('[data-walk-go]').forEach(r=>r.onclick=()=>{walkAt=+r.dataset.walkGo;walkNote='';render()});
 document.querySelectorAll('[data-walk-prev]').forEach(b=>b.onclick=()=>{walkAt=Math.max(0,walkAt-1);walkNote='';render()});
 document.querySelectorAll('[data-walk-all]').forEach(b=>b.onclick=async()=>{const todo=walkOpen().filter(d=>d.recommendation);if(!confirm(`Append ${todo.length} review(s), each as "operator, accepting <session>'s recommendation"?`))return;b.disabled=true;let n=0;for(const d of todo){try{const v=await postReview(accepted(d));if(!v.ok){walkNote=`stopped at ${d.entry.id}: ${v.error} (${n} appended)`;break}n++}catch(e){walkNote=`stopped at ${d.entry.id}: ${e.message} (${n} appended)`;break}}if(n===todo.length)walkNote=`${n} recommendation(s) confirmed`;refresh()});
 document.querySelectorAll('form[data-revise]').forEach(f=>f.onsubmit=async ev=>{ev.preventDefault();const out=f.querySelector('.revise-result');try{const r=await fetch('/api/reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision:f.dataset.revise,project:f.dataset.project,assessment:f.assessment.value,reason:f.reason.value,reviewer:'operator',revises:f.dataset.revises})}),v=await r.json();out.textContent=v.ok?' appended -- this revision now counts':' refused: '+v.error;if(v.ok){f.reason.blur();refresh()}}catch(e){out.textContent=' failed: '+e.message}});
 document.querySelectorAll('form[data-review]').forEach(f=>f.onsubmit=async ev=>{ev.preventDefault();const out=f.querySelector('.review-result');const body={decision:f.dataset.review,project:f.dataset.project,assessment:f.assessment.value,reviewer:f.reviewer.value,reason:f.reason.value};try{const r=await fetch('/api/reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),v=await r.json();out.textContent=v.ok?' appended -- Autobuilder follows it at its next proposal':' refused: '+v.error;if(v.ok)refresh()}catch(e){out.textContent=' failed: '+e.message}});
 document.querySelectorAll('[data-ticket-link]').forEach(a=>a.onclick=()=>{ticketSearch=a.dataset.ticketLink;ticketStatus='All statuses';ticketTier='All tiers'});
 document.querySelectorAll('[data-tier]').forEach(a=>a.onclick=()=>{ticketTier=a.dataset.tier});
 document.querySelectorAll('[data-ticket]').forEach(b=>b.onclick=async()=>{const id=b.dataset.ticket;ticketDetail={id,text:'Loading…'};render();try{const r=await fetch('/api/tickets/'+encodeURIComponent(id),{cache:'no-store'}),v=await r.json();ticketDetail=v.ok?v.data:{id,error:v.error}}catch(e){ticketDetail={id,error:e.message}}render()});
 if($('#ticket-search')){
  $('#ticket-search').oninput=e=>{const cursor=e.target.selectionStart;ticketSearch=e.target.value;render();$('#ticket-search').focus();$('#ticket-search').setSelectionRange(cursor,cursor)};
  $('#ticket-status').onchange=e=>{ticketStatus=e.target.value;render()};
  $('#ticket-tier').onchange=e=>{ticketTier=e.target.value;render()};
 }

}
async function refresh(){if(busy)return;busy=true;$('#refresh').disabled=true;try{const r=await fetch('/api/snapshot',{cache:'no-store',signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error(`HTTP ${r.status}`);snapshot=await r.json();updated=new Date()}catch(e){snapshot={status:{ok:false,error:`Cannot reach Observatory proxy: ${e.message}`}};updated=new Date()}finally{busy=false;$('#refresh').disabled=false;render()}}
$('#refresh').onclick=refresh;
$('#export').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({checkedAt:updated,sources:snapshot},null,2)],{type:'application/json'}));a.href=url;a.download='autobuilder-live-snapshot.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
window.onhashchange=render;render();refresh();setInterval(()=>{if(!document.activeElement?.closest?.('form'))refresh()},5000);
